using Npgsql;using QuestPDF.Infrastructure;using SistemaPrestamos.Api.Services;
QuestPDF.Settings.License=LicenseType.Community;var cs=Environment.GetEnvironmentVariable("PROBE_CONNECTION")??throw new Exception("Missing connection");var output=Environment.GetEnvironmentVariable("CASH_OUTPUT")??Directory.GetCurrentDirectory();var date=new DateOnly(2026,7,12);await using var source=NpgsqlDataSource.Create(cs);var repo=new CierreCajaRepository(source);var pdf=new CierreCajaPdfService(repo);
