finally{await using(var detail=source.CreateCommand("DELETE FROM prestamos.cierre_caja_detalle WHERE id_cierre IN(SELECT id_cierre FROM prestamos.cierres_caja WHERE fecha=$1 AND usuario='Codex')")){detail.Parameters.AddWithValue(date);await detail.ExecuteNonQueryAsync();}await using var close=source.CreateCommand("DELETE FROM prestamos.cierres_caja WHERE fecha=$1 AND usuario='Codex'");close.Parameters.AddWithValue(date);await close.ExecuteNonQueryAsync();}
